def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def counted(s):
    return norm_status(s) in ("delivered", "delivered_late")


def num(s):
    s = str(s).strip().replace(" ", "")
    if "," in s and "." not in s:
        s = s.replace(",", ".")
    elif "," in s:
        s = s.replace(",", "")
    return Fraction(s)


def unit_factor(u):
    return UNITS[u.strip().lower().rstrip(".")]


