    if m:
        return int(m[3]), MONTHS[m[2].lower()]
    m = re.fullmatch(r"([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),?\s+(\d{4})", s)
    if m:
        return int(m[3]), MONTHS[m[1].lower()]
    m = re.fullmatch(r"(\d{1,2})\.(\d{1,2})\.(\d{4})", s)
    if m:
        return int(m[3]), int(m[2])
    m = re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})", s)
    if m:
        return int(m[3]), int(m[1])
    raise ValueError("unparseable date: %r" % s)


