    for d in sorted(res):
        t = res[d]["total"]
        q = (Decimal(t.numerator) / Decimal(t.denominator)) if False else None
        from decimal import getcontext
        getcontext().prec = 60
        q = (Decimal(t.numerator) / Decimal(t.denominator)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        out["depots"][d] = {"shipments": res[d]["shipments"], "total_kg": float(q)}
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


