                   if os.path.isfile(os.path.join(data_dir, f)) and not f.startswith("."))
    depots = {}
    for f in files:
        depots[os.path.splitext(f)[0]] = read_file(os.path.join(data_dir, f))

    def rank(d):
        return (ORDER.index(d), d) if d in ORDER else (len(ORDER), d)

    seen = {}      # number -> (depot, rec)
    count_in = {}  # number -> set of depots
    for d in sorted(depots, key=rank):
        for rec in depots[d]:
            count_in.setdefault(rec[0], set()).add(d)
            if rec[0] not in seen:
                seen[rec[0]] = (d, rec)
    res = {d: {"shipments": 0, "total": Fraction(0)} for d in depots}
    months = {}
    for n, (d, (_, ym, kg, status)) in seen.items():
        if counted(status):
            res[d]["shipments"] += 1
            res[d]["total"] += kg
            k = "%04d-%02d" % ym
            months[k] = months.get(k, 0) + 1
    out = {"depots": {}, "by_month": {k: months[k] for k in sorted(months)},
           "duplicates_resolved": sum(1 for s in count_in.values() if len(s) > 1)}
    for d in sorted(res):
        t = res[d]["total"]
        q = (Decimal(t.numerator) / Decimal(t.denominator)) if False else None
        from decimal import getcontext
        getcontext().prec = 60
        q = (Decimal(t.numerator) / Decimal(t.denominator)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        out["depots"][d] = {"shipments": res[d]["shipments"], "total_kg": float(q)}
    with open(out_file, "w") as f:
        json.dump(out, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()
